#!/usr/bin/env bash
set -euo pipefail

rm -rf dist
mkdir -p dist
cp index.html styles.css app.js purchase-engine.js catalog-controls.js cloudflare-sync.js ui-translation-extra.js sw.js master.json manifest.webmanifest hero-food.jpg hero-bar.jpg LRX-LOGO-PLANTILLAS.png LRX-LOGO-IMPRESION-TRANSPARENTE.png dist/
mkdir -p dist/assets
cp -R assets/utensils dist/assets/

python3 - <<'PY'
from pathlib import Path
p = Path("dist/app.js")
s = p.read_text()
needle = "function updateLanguageChip(){"
bridge = "const __lrxApplyEnglishUI=applyEnglishUI;const __lrxOriginalAttrs=new WeakMap();const __lrxOriginalNodes=new WeakMap();const __lrxOriginalOptions=new WeakMap();let __lrxTranslateKeys=Object.keys(UI_EN).filter(k=>k.length>2).sort((a,b)=>b.length-a.length);const __lrxTranslateText=value=>{if(state.settings?.language!=='en')return value;let out=UI_EN[value]||value;out=out.replace(/Showing (\\d+[–-]\\d+) de (\\d+) records · Page (\\d+) de (\\d+)/g,'Showing $1 of $2 records · Page $3 of $4');out=out.replace(/Showing (\\d+[–-]\\d+) de (\\d+) · Page (\\d+) de (\\d+)/g,'Showing $1 of $2 · Page $3 of $4');out=out.replace(/\\bNet sales\\s+por canal\\b/gi,'Net sales by channel');return out};applyEnglishUI=function(){const before=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=before.nextNode())if(!__lrxOriginalNodes.has(n))__lrxOriginalNodes.set(n,lrxOriginalText?.get(n)||n.nodeValue||'');__lrxApplyEnglishUI();const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(n=w.nextNode()){const current=n.nodeValue||'',fromOriginal=__lrxOriginalNodes.get(n)||'',translatedCurrent=__lrxTranslateText(current),translatedOriginal=__lrxTranslateText(fromOriginal),next=translatedCurrent!==current?translatedCurrent:translatedOriginal;if(state.settings?.language==='en'){const monthNames={Enero:'January',Febrero:'February',Marzo:'March',Abril:'April',Mayo:'May',Junio:'June',Julio:'July',Agosto:'August',Septiembre:'September',Octubre:'October',Noviembre:'November',Diciembre:'December'};document.querySelectorAll('#content button').forEach(button=>{const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const current=node.nodeValue||'',raw=__lrxOriginalNodes.get(node)||current,match=raw.match(/^(\\s*)(Enero|Febrero|Marzo|Abril|Mayo|Junio|Julio|Agosto|Septiembre|Octubre|Noviembre|Diciembre)(?=\\s|$)/);if(match){const next=match[1]+monthNames[match[2]]+raw.slice(match[0].length);if(current!==next)node.nodeValue=next}}})}};document.querySelectorAll('option').forEach(option=>{const current=option.textContent||'',node=option.firstChild,raw=node&&__lrxOriginalNodes.get(node)||current;let original=__lrxOriginalOptions.get(option);if(!original){original={text:raw,last:current};__lrxOriginalOptions.set(option,original)}else if(current!==original.last)original.text=raw;const next=state.settings?.language==='en'?__lrxTranslateText(original.text):original.text;if(current!==next)option.textContent=next;original.last=next});document.querySelectorAll('[aria-label],[title],[placeholder]').forEach(el=>{let original=__lrxOriginalAttrs.get(el);if(!original){original={};__lrxOriginalAttrs.set(el,original)}for(const attr of ['aria-label','title','placeholder']){const current=el.getAttribute(attr);if(current===null)continue;if(!(attr in original)||current!==original['last'+attr])original[attr]=current;const next=state.settings?.language==='en'?__lrxTranslateText(original[attr]):original[attr];if(current!==next)el.setAttribute(attr,next);original['last'+attr]=next}})};window.extendLRXEnglishDictionary=extra=>{for(const [key,value] of Object.entries(extra||{})){UI_EN[key]=value;try{const repaired=decodeURIComponent(escape(key));if(repaired!==key)UI_EN[repaired]=value}catch{}}__lrxTranslateKeys=Object.keys(UI_EN).filter(k=>k.length>2).sort((a,b)=>b.length-a.length);applyEnglishUI()};const __lrxTranslationObserver=new MutationObserver(()=>{if(state.settings?.language==='en')applyEnglishUI()});__lrxTranslationObserver.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['aria-label','title']});function updateLanguageChip(){"
if "window.extendLRXEnglishDictionary" not in s:
    if needle not in s:
        raise SystemExit("Could not find language UI insertion point")
    s = s.replace(needle, bridge, 1)
    p.write_text(s)
PY
